DROP SCHEMA IF EXISTS f1 CASCADE;
CREATE SCHEMA IF NOT EXISTS f1;
SET search_path TO f1;

CREATE TYPE "tire_type" AS ENUM (
  'soft',
  'medium',
  'hard',
  'intermediate',
  'wet'
);

CREATE TABLE "drivers" (
  "driver_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "team_id" integer NOT NULL,
  "first_name" varchar(30) NOT NULL,
  "last_name" varchar(30) NOT NULL,
  "number" integer NOT NULL,
  "birthday" date NOT NULL,
  "nationality" varchar(30) NOT NULL,
  "championship_wins" integer,
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "formulas" (
  "formula_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "team_id" integer NOT NULL,
  "model_name" varchar(30) NOT NULL,
  "engine_supplier" varchar(30) NOT NULL
);

CREATE TABLE "teams" (
  "team_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(30) NOT NULL,
  "base_country" varchar(30) NOT NULL,
  "principal" varchar(30) NOT NULL,
  "constructor_wins" integer,
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "circuits" (
  "circuit_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(30) NOT NULL,
  "country" varchar(30) NOT NULL,
  "length_km" float
);

CREATE TABLE "races" (
  "race_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "circuit_id" integer NOT NULL,
  "name" varchar(30) NOT NULL,
  "season_year" integer,
  "race_date" date
);

CREATE TABLE "pit_stops" (
  "pit_stop_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "race_id" integer NOT NULL,
  "driver_id" integer NOT NULL,
  "lap_number" int,
  "tire_type" tire_type,
  "duration_seconds" float
);

CREATE TABLE "race_results" (
  "result_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "race_id" integer NOT NULL,
  "driver_id" integer NOT NULL,
  "starting_position" integer,
  "finishing_position" integer,
  "lap_number" integer,
  "duration_seconds" float,
  "is_classified" boolean NOT NULL DEFAULT true
);

CREATE INDEX ON "pit_stops" ("driver_id");

CREATE INDEX ON "pit_stops" ("race_id");

CREATE UNIQUE INDEX ON "race_results" ("race_id", "driver_id");

CREATE INDEX ON "race_results" ("race_id");

CREATE INDEX ON "race_results" ("driver_id");

COMMENT ON COLUMN "race_results"."is_classified" IS 'True = jezdec byl klasifikován v cíli (DNF = false).';

ALTER TABLE "drivers" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "formulas" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "races" ADD FOREIGN KEY ("circuit_id") REFERENCES "circuits" ("circuit_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pit_stops" ADD FOREIGN KEY ("race_id") REFERENCES "races" ("race_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pit_stops" ADD FOREIGN KEY ("driver_id") REFERENCES "drivers" ("driver_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "race_results" ADD FOREIGN KEY ("race_id") REFERENCES "races" ("race_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "race_results" ADD FOREIGN KEY ("driver_id") REFERENCES "drivers" ("driver_id") DEFERRABLE INITIALLY IMMEDIATE;
